import{PRODUCTS as e,getCategories as t}from"../data.js";import{formatPrice as r}from"../format.js";import{addToCart as o}from"../store.js";import{navigate as a}from"../router.js";export function renderHome(a){const n=t();let c={search:"",category:"all",sort:"featured"};a.innerHTML=`\n    <section class="catalog-hero">\n      <p class="eyebrow">Capstone project</p>\n      <h1>Foundry Goods</h1>\n      <p class="lede">A small, well-made catalog — every product here is a\n        stand-in for a real storefront's data layer.</p>\n    </section>\n\n    <section class="catalog-controls" aria-label="Filter and sort products">\n      <div class="field">\n        <label for="search">Search</label>\n        <input type="search" id="search" placeholder="Search products…" autocomplete="off">\n      </div>\n      <div class="field">\n        <label for="category">Category</label>\n        <select id="category">\n          <option value="all">All categories</option>\n          ${n.map(e=>`<option value="${e}">${e}</option>`).join("")}\n        </select>\n      </div>\n      <div class="field">\n        <label for="sort">Sort by</label>\n        <select id="sort">\n          <option value="featured">Featured</option>\n          <option value="price-asc">Price: low to high</option>\n          <option value="price-desc">Price: high to low</option>\n          <option value="rating">Rating</option>\n        </select>\n      </div>\n    </section>\n\n    <p id="result-count" class="result-count" role="status" aria-live="polite"></p>\n    <div id="catalog-grid" class="catalog-grid"></div>\n  `;const s=a.querySelector("#search"),l=a.querySelector("#category"),i=a.querySelector("#sort"),d=a.querySelector("#catalog-grid"),p=a.querySelector("#result-count");function u(){const t=function(){let t=e.filter(e=>{const t=e.name.toLowerCase().includes(c.search.toLowerCase()),r="all"===c.category||e.category===c.category;return t&&r});return"price-asc"===c.sort&&(t=[...t].sort((e,t)=>e.price-t.price)),"price-desc"===c.sort&&(t=[...t].sort((e,t)=>t.price-e.price)),"rating"===c.sort&&(t=[...t].sort((e,t)=>t.rating-e.rating)),t}();p.textContent=`${t.length} product${1===t.length?"":"s"}`,0!==t.length?(d.innerHTML=t.map(e=>`\n      <article class="product-card">\n        <a href="#/product/${e.id}" class="product-card-media">\n          <img src="${e.image}" alt="${e.name}" width="600" height="450" loading="lazy" decoding="async">\n        </a>\n        <div class="product-card-body">\n          <p class="product-card-category">${e.category}</p>\n          <h3><a href="#/product/${e.id}">${e.name}</a></h3>\n          <p class="product-card-price">${r(e.price)}</p>\n        </div>\n        <button type="button" class="btn btn-outline btn-add" data-id="${e.id}">Add to cart</button>\n      </article>\n    `).join(""),d.querySelectorAll(".btn-add").forEach(e=>{e.addEventListener("click",()=>{o(e.dataset.id,1),e.textContent="Added ✓",setTimeout(()=>{e.textContent="Add to cart"},1200)})})):d.innerHTML='<p class="empty-state">No products match your search.</p>'}s.addEventListener("input",e=>{c.search=e.target.value,u()}),l.addEventListener("change",e=>{c.category=e.target.value,u()}),i.addEventListener("change",e=>{c.sort=e.target.value,u()}),u()}